  (12, 3, 'bike', 20, null, 2, 3, 'Easy, conversational effort.'),
  (12, 4, 'bike', 15, null, 2, 3, 'Easy, conversational effort.'),
  (12, 5, 'bike', 20, null, 2, 3, 'Easy, conversational effort.'),
  (12, 6, 'bike', 40, 50, 2, 3, 'Conversational pace. No intervals. Incline treadmill walking is fine once tolerated.')
) as v (week_number, day_of_week, modality, target_minutes, target_minutes_max, target_rpe_min, target_rpe_max, notes)
on conflict (program_block_id, week_number, day_of_week) do update set modality = excluded.modality,
  target_minutes = excluded.target_minutes, target_minutes_max = excluded.target_minutes_max,
  target_rpe_min = excluded.target_rpe_min, target_rpe_max = excluded.target_rpe_max, notes = excluded.notes;

commit;
